frappe.ui.form.on('Appraisal', {
    refresh: function(frm) {
        // Get the current workflow state (Default to Draft if empty)
        let state = frm.doc.workflow_state || "Draft";

        // Logic to determine which circles are lit up green
        let step1 = true; // Draft is always step 1
        let step2 = (state === "Pending Manager Review" || state === "Completed");
        let step3 = (state === "Completed");

        // The ACCESS Connect green color, and default gray
        let activeColor = "#16a34a";
        let inactiveColor = "#d1d5db";

        // Build the beautiful HTML structure
        let html = `
            <div style="display: flex; justify-content: space-between; align-items: center; padding: 20px 40px; background-color: #f9fafb; border-radius: 8px; border: 1px solid #e5e7eb; margin-bottom: 15px;">
                
                <div style="text-align: center; flex: 1; z-index: 2;">
                    <div style="width: 35px; height: 35px; margin: 0 auto; border-radius: 50%; line-height: 35px; color: white; background-color: ${step1 ? activeColor : inactiveColor}; font-weight: bold; font-size: 16px;">1</div>
                    <div style="margin-top: 10px; font-size: 13px; font-weight: bold; color: ${step1 ? activeColor : '#6b7280'};">Self-Appraisal</div>
                </div>
                
                <div style="height: 4px; flex: 2; background-color: ${step2 ? activeColor : inactiveColor}; margin: 0 -20px; margin-bottom: 25px; z-index: 1;"></div>
                
                <div style="text-align: center; flex: 1; z-index: 2;">
                    <div style="width: 35px; height: 35px; margin: 0 auto; border-radius: 50%; line-height: 35px; color: white; background-color: ${step2 ? activeColor : inactiveColor}; font-weight: bold; font-size: 16px;">2</div>
                    <div style="margin-top: 10px; font-size: 13px; font-weight: bold; color: ${step2 ? activeColor : '#6b7280'};">Manager Review</div>
                </div>
                
                <div style="height: 4px; flex: 2; background-color: ${step3 ? activeColor : inactiveColor}; margin: 0 -20px; margin-bottom: 25px; z-index: 1;"></div>
                
                <div style="text-align: center; flex: 1; z-index: 2;">
                    <div style="width: 35px; height: 35px; margin: 0 auto; border-radius: 50%; line-height: 35px; color: white; background-color: ${step3 ? activeColor : inactiveColor}; font-weight: bold; font-size: 16px;">3</div>
                    <div style="margin-top: 10px; font-size: 13px; font-weight: bold; color: ${step3 ? activeColor : '#6b7280'};">Completed</div>
                </div>
                
            </div>
        `;

        // Inject the HTML into the form
        frm.set_df_property('custom_status_dashboard', 'options', html);
    }
});

