frappe.ui.form.on('Appraisal', {
    refresh: function(frm) {
        lock_overview_tab(frm);
        render_progress_bar(frm);
        force_correct_header_badge(frm);
        lock_and_clean_overview_tab(frm);

        if (!$('#hide-grid-placeholders-css').length) {
            $('head').append(`
                <style id="hide-grid-placeholders-css">
                    .grid-row input::placeholder, 
                    .grid-row textarea::placeholder,
                    .control-input textarea::placeholder {
                        color: transparent !important;
                    }

                    .grid-static-col:empty::before {
                        content: "" !important;
                    }

                    .stepper-container {
                        margin-bottom: 25px !important;
                        padding: 10px 0;
                        background: transparent;
                    }

                    /* OBJECTIVES & ACHIEVEMENTS: Auto-grow up to 160px */
                    [data-fieldname="custom_objectives__achievements"] .grid-row {
                        min-height: 160px !important;
                        height: 160px;
                        align-items: stretch !important;
                    }

                    [data-fieldname="custom_objectives__achievements"] .grid-row .grid-row-col,
                    [data-fieldname="custom_objectives__achievements"] .grid-row .grid-static-col {
                        min-height: 160px !important;
                        height: 160px;
                    }

                    [data-fieldname="custom_objectives__achievements"] .grid-row textarea {
                        min-height: 160px !important;
                        height: 160px;
                        max-height: 300px;
                        overflow-y: auto !important;
                        overflow-x: hidden !important;
                        resize: none !important;
                        white-space: pre-wrap !important;
                        word-wrap: break-word !important;
                        box-sizing: border-box !important;
                    }
                </style>
            `);
        }

        if (frm.fields_dict.custom_objectives__achievements && frm.fields_dict.custom_objectives__achievements.grid) {
            let grid = frm.fields_dict.custom_objectives__achievements.grid;
            grid.grid_rows.forEach(row => {
                if (row.doc.objective === 'Objective') row.doc.objective = '';
                if (row.doc.how_will_you_achieve === 'How will you achieve') row.doc.how_will_you_achieve = '';
                if (row.doc.midterm_achievements === 'Mid-term achievements') row.doc.midterm_achievements = '';
                if (row.doc.annual_achievements === 'Annual achievements') row.doc.annual_achievements = '';
            });
            grid.refresh();
            setTimeout(() => {
                $('[data-fieldname="custom_objectives__achievements"] textarea').each(function () {
                    $(this).trigger('input');
                });
            }, 300);
        }

        setTimeout(() => {
            $('.grid-row input, textarea').each(function() {
                let val = $(this).val() || '';
                if (['Objective', 'How will you achieve', 'Mid-term achievements', 'Annual achievements'].includes(val.trim())) {
                    $(this).val('').trigger('change');
                }
                if (val.includes('Feedback to your manager about how you feel')) {
                    $(this).val('').trigger('change');
                }
            });
        }, 200);

        // Fetch cycle details to determine Mid-Term vs Annual based on Cycle Type field
        if (frm.doc.appraisal_cycle) {
            frappe.db.get_value('Appraisal Cycle', frm.doc.appraisal_cycle, ['status', 'end_date', 'custom_cycle_type'])
            .then(r => {
                if (r && r.message) {
                    frm._cycle_type = r.message.custom_cycle_type;
                    apply_manager_security_lock(frm);
                    setup_competencies(frm);
                    toggle_mid_term_vs_annual(frm);
                    check_cycle_dates_and_lock(frm);
                    enforce_field_visibility(frm);
                    sync_status_columns(frm);
                    render_progress_bar(frm);
                    force_correct_header_badge(frm);

                    let cycle = get_cycle_type(frm);
                    if (cycle.is_annual && frm.doc.employee) {
                        fetch_and_render_mid_term(frm);
                    }
                }
            });
        } else {
            apply_manager_security_lock(frm);
            setup_competencies(frm);
        }

        // Native smooth tab switching listener
        if (!frm.tab_listener_bound) {
            frm.tab_listener_bound = true;
            frm.page.wrapper.on('shown.bs.tab', function() {
                let current_cycle = get_cycle_type(frm);
                if (current_cycle.is_annual) {
                    enforce_field_visibility(frm);
                }
            });
        }

        // Clean removal of standard "View Goals" button
        setTimeout(() => {
            let btn = $('button:contains("View Goals")');
            if (btn.is(':visible')) {
                frm.remove_custom_button('View Goals');
                btn.hide(); 
            }
        }, 300);

        if (!frm.objective_autogrow_bound) {
            frm.objective_autogrow_bound = true;
            $(document).on(
                'input.objectiveAutoGrow',
                '[data-fieldname="custom_objectives__achievements"] textarea',
                function () {
                    const textarea = this;
                    const row = $(textarea).closest('.grid-row');
                    textarea.style.setProperty('height', '160px', 'important');
                    let requiredHeight = textarea.scrollHeight;
                    requiredHeight = Math.max(requiredHeight, 160);
                    requiredHeight = Math.min(requiredHeight, 300);

                    textarea.style.setProperty('height', requiredHeight + 'px', 'important');
                    row[0].style.setProperty('height', requiredHeight + 'px', 'important');
                    row[0].style.setProperty('min-height', requiredHeight + 'px', 'important');

                    row.find('.grid-row-col, .grid-static-col').each(function () {
                        this.style.setProperty('height', requiredHeight + 'px', 'important');
                        this.style.setProperty('min-height', requiredHeight + 'px', 'important');
                    });
                }
            );
        }
    },

    appraisal_cycle: function(frm) {
        if (frm.doc.appraisal_cycle) {
            frappe.db.get_value('Appraisal Cycle', frm.doc.appraisal_cycle, ['status', 'end_date', 'custom_cycle_type'])
            .then(r => {
                if (r && r.message) {
                    frm._cycle_type = r.message.custom_cycle_type;
                    apply_manager_security_lock(frm);
                    setup_competencies(frm);
                    render_progress_bar(frm);
                    toggle_mid_term_vs_annual(frm);
                    check_cycle_dates_and_lock(frm);
                    enforce_field_visibility(frm);
                    sync_status_columns(frm);

                    let cycle = get_cycle_type(frm);
                    if (cycle.is_annual && frm.doc.employee) {
                        fetch_and_render_mid_term(frm);
                    }
                }
            });
        }
    },

    employee: function(frm) {
        setTimeout(() => {
            render_progress_bar(frm);
            let cycle = get_cycle_type(frm);
            if (cycle.is_annual && frm.doc.employee) {
                fetch_and_render_mid_term(frm);
            }
            apply_manager_security_lock(frm);
            setup_competencies(frm);
            if (frm.doc.appraisal_cycle) {
                enforce_field_visibility(frm);
                sync_status_columns(frm);
            }
        }, 300);
    },

    validate: function(frm) {
        if (frm.doc.self_ratings && frm.doc.self_ratings.length > 0) {
            let total = frm.doc.self_ratings.length;
            let base_weight = Math.floor(100 / total);
            let remainder = 100 - (base_weight * total);
            $.each(frm.doc.self_ratings, function(i, row) { row.weightage = (i === 0) ? (base_weight + remainder) : base_weight; });
        }
        if (frm.doc.goals && frm.doc.goals.length > 0) {
            let total = frm.doc.goals.length;
            let base_weight = Math.floor(100 / total);
            let remainder = 100 - (base_weight * total);
            $.each(frm.doc.goals, function(i, row) { row.per_weightage = (i === 0) ? (base_weight + remainder) : base_weight; });
        }
    },

    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action && frm.selected_workflow_action.includes('Finalize')) {
            let cycle = get_cycle_type(frm);

            if (cycle.is_annual) {
                let missing_competency = false;
                let tables = ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'];
                
                tables.forEach(table => {
                    if (frm.fields_dict[table] && !frm.get_docfield(table).hidden && frm.doc[table]) {
                        frm.doc[table].forEach(row => {
                            if (!row.annual_rating) {
                                missing_competency = true;
                            }
                        });
                    }
                });

                if (missing_competency) {
                    frappe.throw(__('Please fill out all ratings in the <b>Technical & Behavioural Competencies</b> tab before finalizing.'));
                }

                if (!frm.doc.custom_annual_manager_feedback && !frm.doc.custom_manager_review__feedback) {
                    frappe.throw(__('Please provide the <b>Annual Manager Feedback</b> before finalizing.'));
                }
                if (!frm.doc.custom_annual_manager_rating) {
                    frappe.throw(__('Please select the <b>Annual Manager Rating</b> before finalizing.'));
                }
            } else if (cycle.is_mid_term) {
                if (!frm.doc.custom_midterm_manager_feedback) {
                    frappe.throw(__('Please provide the <b>Manager Appraisal (Mid-Term)</b> feedback before finalizing.'));
                }
            }
        }
    }
});

