// --- HELPER FUNCTIONS ---

function sync_status_columns(frm) {
    if (frm.is_new()) return; 
    let cycle = get_cycle_type(frm);
    let state = frm.doc.workflow_state || 'Draft';

    if (cycle.is_mid_term) {
        let expected_obj = 'Pending';
        let expected_mid = 'Pending';
        let expected_ann = 'N/A';

        if (state === 'Draft' || state === 'Pending') {
            expected_obj = 'Pending'; expected_mid = 'Pending';
        } else if (state === 'Objective Review Pending') {
            expected_obj = 'Under Review'; expected_mid = 'Pending';
        } else if (state === 'Objectives Approved') {
            expected_obj = 'Approved'; expected_mid = 'Pending';
        } else if (state === 'Pending Manager Review') {
            expected_obj = 'Approved'; expected_mid = 'Manager Review';
        } else if (state === 'Completed') {
            expected_obj = 'Approved'; expected_mid = 'Completed';
        }

        if (frm.fields_dict.custom_objective_status) frm.doc.custom_objective_status = expected_obj;
        if (frm.fields_dict.custom_midterm_status) frm.doc.custom_midterm_status = expected_mid;
        if (frm.fields_dict.custom_annual_status) frm.doc.custom_annual_status = expected_ann;
        frm.refresh_fields(['custom_objective_status', 'custom_midterm_status', 'custom_annual_status']);
    } else if (cycle.is_annual && frm.doc.employee) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Appraisal',
                filters: {
                    employee: frm.doc.employee,
                    docstatus: ['<', 2],
                    name: ['!=', frm.doc.name]
                },
                fields: ['name', 'appraisal_cycle', 'custom_objective_status', 'custom_midterm_status', 'workflow_state'],
                order_by: 'creation desc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let mid_term = r.message.find(d => {
                        let c = (d.appraisal_cycle || '').toLowerCase();
                        return c.includes('mid') || c.includes('half') || d.name === frm.doc.custom_linked_midterm_appraisal;
                    }) || r.message[0];

                    let live_obj = (mid_term && mid_term.custom_objective_status) ? mid_term.custom_objective_status : 'Pending';
                    let live_mid = (mid_term && mid_term.custom_midterm_status) ? mid_term.custom_midterm_status : 'Pending';
                    
                    let live_ann = 'N/A';
                    if (live_mid === 'Completed') {
                        if (state === 'Draft' || state === 'Pending') live_ann = 'Pending';
                        else if (state === 'Pending Manager Review') live_ann = 'Manager Review';
                        else if (state === 'Completed') live_ann = 'Completed';
                        else live_ann = 'Pending';
                    }

                    if (frm.fields_dict.custom_objective_status) frm.doc.custom_objective_status = live_obj;
                    if (frm.fields_dict.custom_midterm_status) frm.doc.custom_midterm_status = live_mid;
                    if (frm.fields_dict.custom_annual_status) frm.doc.custom_annual_status = live_ann;
                    frm.refresh_fields(['custom_objective_status', 'custom_midterm_status', 'custom_annual_status']);
                }
            }
        });
    }
}

