function calculate_tenure(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        // Prevent negative calculations if the dates are backwards
        if (frm.doc.start_date > frm.doc.end_date) {
            frappe.msgprint('Warning: End Date cannot be before Start Date!');
            frm.set_value('project_tenure', '');
            return;
        }

        let start = moment(frm.doc.start_date);
        let end = moment(frm.doc.end_date);

        // Calculate exact Years, Months, and Days
        let years = end.diff(start, 'years');
        start.add(years, 'years');
        
        let months = end.diff(start, 'months');
        start.add(months, 'months');
        
        let days = end.diff(start, 'days');

        // Build the text cleanly (e.g., hiding "0 Years" if it is only a 6-month contract)
        let parts = [];
        if (years > 0) parts.push(years + (years === 1 ? ' Year' : ' Years'));
        if (months > 0) parts.push(months + (months === 1 ? ' Month' : ' Months'));
        if (days > 0) parts.push(days + (days === 1 ? ' Day' : ' Days'));

        let final_text = parts.length > 0 ? parts.join(', ') : '0 Days';

        // Drop the final formatted text into your tenure box
        frm.set_value('project_tenure', final_text);
    }
}

