        // ------------------------------------------------------

        let review_fields = [
            "lead_approver_review",
            "legal_approver_review",
            "finance_approver_review",
            "hr_approver_review",
            "ceo_approver_review"
        ];


        review_fields.forEach(function(field) {

            if (
                frm.fields_dict[field] &&
                frm.fields_dict[field].$input
            ) {

                frm.fields_dict[field].$input.css({
                    "height": "36px",
                    "min-height": "36px"
                });
            }
        });


        // ------------------------------------------------------
        // Separate File Upload Restrictions
        // ------------------------------------------------------
        toggle_signed_document(frm);

        setup_contract_upload(frm);
setup_budget_upload(frm);
setup_project__proposal_upload(frm);
setup_proposal_budget_upload(frm);
setup_signed_document_upload(frm);

    },


    // ==========================================================
    // VALIDATE
    // ==========================================================

    validate: function(frm) {

        // ======================================================
        // BACKUP DOCUMENT VALIDATION
        // ======================================================

        validate_contract_file(frm);
        validate_budget_file(frm);
        validate_project__proposal_file(frm);
        validate_proposal_budget_file(frm);
        validate_signed_document_file(frm);

        let state = frm.doc.workflow_state || "";
        const pending_stages = {
            "Pending Team Lead Approval": { field: "lead_approver_review", approver: "lead_approver", old_val: frm.custom_old_lead },
            "Pending Level 2.1 Legal Approval": { field: "legal_approver_review", approver: "legal_approver", old_val: frm.custom_old_legal },
            "Pending Level 2.2 Finance Approval": { field: "finance_approver_review", approver: "finance_approver", old_val: frm.custom_old_finance },
            "Pending Level 2.3 HR Approval": { field: "hr_approver_review", approver: "hr_approver", old_val: frm.custom_old_hr },
            "Pending CEO Approval": { field: "ceo_approver_review", approver: "ceo_approver", old_val: frm.custom_old_ceo }
        };

        // If new or not in an active pending approval stage (e.g. Draft, In Progress, Commenced), skip review authorization check!
        if (frm.is_new() || !state || !pending_stages[state]) {
            return;
        }

        if (frappe.session.user === "Administrator") {
            return;
        }

        // Only check the single currently active stage's review field
        let stage_cfg = pending_stages[state];
        let current_val = (frm.doc[stage_cfg.field] || "").trim();
        let old_val = (stage_cfg.old_val || "").trim();

        if (current_val && current_val !== old_val) {
            let assigned_approver = frm.doc[stage_cfg.approver];
            if (assigned_approver && frappe.session.user !== assigned_approver) {
                frappe.throw({
                    title: "Not Authorized",
                    message: "You are not authorized! Only the assigned approver can write here."
                });
            }
        }
    },

    before_workflow_action: async function(frm) {

        let action =
            frm.selected_workflow_action || "";

        let state =
            frm.doc.workflow_state || "";


        // ======================================================
        // APPROVE ONLY
        // REJECT IS HANDLED BY SEPARATE REJECT POPUP SCRIPT
        // ======================================================

        if (
            !action.toLowerCase().includes("approve")
        ) {
            return;
        }


        // ======================================================
        // FIND CORRECT STATUS FIELD
        // ======================================================

        let status_field = "";

        let review_field = "";


        if (
            state === "Pending Team Lead Approval"
        ) {

            status_field =
                "lead_approver_status";

            review_field =
                "lead_approver_review";

        }

        else if (
            state === "Pending Level 2.1 Legal Approval"
        ) {

            status_field =
                "legal_approver_status";

            review_field =
                "legal_approver_review";

        }

        else if (
            state === "Pending Level 2.2 Finance Approval"
        ) {

            status_field =
                "finance_approver_status";

            review_field =
                "finance_approver_review";

        }

        else if (
            state === "Pending Level 2.3 HR Approval"
        ) {

            status_field =
                "hr_approver_status";

            review_field =
                "hr_approver_review";

        }

        else if (
            state === "Pending CEO Approval"
        ) {

            status_field =
                "ceo_approver_status";

            review_field =
                "ceo_approver_review";
        }


        // ======================================================
        // SAFETY CHECK
        // ======================================================

        if (!status_field || !review_field) {

            frappe.msgprint({
                title: "Workflow Error",
                indicator: "red",
                message:
                    "Could not determine the correct approver status/review fields."
            });

            return;
        }


        // ======================================================
        // DATE + TIME
        // ======================================================

        let timestamp =
            frappe.datetime.now_datetime();

        let display_timestamp =
            frappe.datetime.str_to_user(timestamp) || timestamp;


        // ======================================================
        // CHECK CURRENT STATUS
        // ======================================================

        let current_status =
            frm.doc[status_field] || "";


        // ======================================================
        // PREVENT DUPLICATE APPROVAL
        // ======================================================

        if (
            current_status &&
            current_status.toLowerCase().includes("approved")
        ) {
            return;
        }


        // ======================================================
        // CREATE STATUS ONLY
        // ======================================================

        let status_text =
            "Approved [" +
            display_timestamp +
            "]";


        // ======================================================
        // SAVE STATUS
        // ======================================================

        await frappe.call({

            method:
                "frappe.client.set_value",

            args: {

                doctype:
                    frm.doc.doctype,

                name:
                    frm.doc.name,

                fieldname:
                    status_field,

                value:
                    status_text
            }
        });


        // ======================================================
        // UPDATE FORM STATUS FIELD
        // ======================================================

        frm.doc[status_field] =
            status_text;

        frm.refresh_field(
            status_field
        );


        // ======================================================
        // KEEP REVIEW SEPARATE
        // ======================================================

        // The review/comment remains ONLY in:
        //
        // lead_approver_review
        // legal_approver_review
        // finance_approver_review
        // hr_approver_review
        // ceo_approver_review
        //
        // We do NOT add Approved/Rejected text to it.


        console.log(
            "Approval status saved:",
            status_field,
            status_text
        );

    }
});


