// ==========================================================
// SIGNED DOCUMENT UPLOAD
// ONLY PDF
// ==========================================================

function setup_signed_document_upload(frm) {

    let field =
        frm.fields_dict["upload_signed_document"];

    if (!field) {
        return;
    }

    field.on_attach_click = function() {
        let state = frm.doc.workflow_state || "Draft";
        let ceo_status = frm.doc.ceo_approver_status || "";
        let is_ceo_approved = (
            state === "In Progress" ||
            state === "Commenced" ||
            state === "Active/Amendment Initiated" ||
            state === "On Hold" ||
            state === "Terminated" ||
            state === "Closed" ||
            (ceo_status && ceo_status.includes("Approved"))
        );

        if (!is_ceo_approved) {
            frappe.msgprint({
                title: "Action Not Allowed",
                indicator: "red",
                message: "<b>Complete Counter Signed Contract</b> can only be uploaded once CEO approval is completed."
            });
            return;
        }

        let is_owner = (frappe.session.user === frm.doc.owner);
        let is_contract_owner = (frm.doc.contract_owner && frappe.session.user === frm.doc.contract_owner);
        let has_cm_role = (frappe.user_roles && (frappe.user_roles.includes("Contract Manager") || frappe.user_roles.includes("System Manager")));
        let is_admin = (frappe.session.user === "Administrator");
        let is_contract_manager = is_owner || is_contract_owner || has_cm_role || is_admin;

        if (!is_contract_manager) {
            frappe.msgprint({
                title: "Not Authorized",
                indicator: "red",
                message: "Only the <b>Contract Manager</b> is authorized to upload the Complete Counter Signed Contract."
            });
            return;
        }

        this.set_upload_options();

        this.upload_options.restrictions = {
            allowed_file_types: [
                ".pdf"
            ]
        };

        this.upload_options.upload_notes =
            "Only PDF (.pdf) files are allowed.";

        this.file_uploader =
            new frappe.ui.FileUploader(
                this.upload_options
            );
    };
}


// ==========================================================
// VALIDATE SIGNED DOCUMENT
// ONLY PDF
// ==========================================================

function validate_signed_document_file(frm) {

    let file_url =
        frm.doc.upload_signed_document;

    // No file = nothing to validate
    if (!file_url) {
        return;
    }

    let state = frm.doc.workflow_state || "Draft";
    let ceo_status = frm.doc.ceo_approver_status || "";
    let is_ceo_approved = (
        state === "In Progress" ||
        state === "Commenced" ||
        state === "Active/Amendment Initiated" ||
        state === "On Hold" ||
        state === "Terminated" ||
        state === "Closed" ||
        (ceo_status && ceo_status.includes("Approved"))
    );

    if (!is_ceo_approved) {
        frm.set_value("upload_signed_document", null);
        frappe.throw({
            title: "Action Not Allowed",
            message: "<b>Complete Counter Signed Contract</b> can only be uploaded once CEO approval is completed."
        });
    }

    let is_owner = (frappe.session.user === frm.doc.owner);
    let is_contract_owner = (frm.doc.contract_owner && frappe.session.user === frm.doc.contract_owner);
    let has_cm_role = (frappe.user_roles && (frappe.user_roles.includes("Contract Manager") || frappe.user_roles.includes("System Manager")));
    let is_admin = (frappe.session.user === "Administrator");
    let is_contract_manager = is_owner || is_contract_owner || has_cm_role || is_admin;

    if (!is_contract_manager) {
        let orig = frm.__orig_upload_signed_document;
        if (file_url !== orig) {
            frm.set_value("upload_signed_document", orig || null);
            frappe.throw({
                title: "Not Authorized",
                message: "Only the <b>Contract Manager</b> is authorized to upload the Complete Counter Signed Contract."
            });
        }
    }

    let file_name =
        file_url
            .split("?")[0]
            .split("/")
            .pop()
            .toLowerCase()
            .trim();

    if (!file_name.endsWith(".pdf")) {

        frappe.throw({
            title: "Invalid Signed Document",

            message:
                "<b>Upload Signed Document</b>" +
                "<br><br>" +
                "Only PDF (.pdf) files are allowed."
        });
    }
}


