        if (!frm.is_new() && !frm.doc.custom_customer_code) {
            frm.set_value('custom_customer_code', frm.doc.name);
            frm.save();
        }
    }
});

frappe.ui.form.on('Customer', {
    // 1. Check live as the user types
    custom_abbreviation: function(frm) {
        if (frm.doc.custom_abbreviation && frm.doc.custom_abbreviation.length > 5) {
            
            // Instantly slice the text back down to exactly 5 characters
            frm.set_value('custom_abbreviation', frm.doc.custom_abbreviation.substring(0, 5));
            
            // Show a quick warning popup
            frappe.show_alert({
                message: __('Abbreviation cannot exceed 5 characters.'),
                indicator: 'orange'
            });
        }
    },

    // 2. Backup check just in case they try to save
    validate: function(frm) {
        if (frm.doc.custom_abbreviation && frm.doc.custom_abbreviation.length > 5) {
            frappe.throw(__('The abbreviation must be 5 characters or less.'));
        }
    }
});

