frappe.ui.form.on("Test Customer Contract", {

    // ==========================================================
    // BEFORE WORKFLOW ACTION
    // REJECT ONLY
    // ==========================================================

    before_workflow_action: function(frm) {

        let action = frm.selected_workflow_action || "";

        // Ignore Approve
        if (!action.toLowerCase().includes("reject")) {
            return;
        }

        let state = frm.doc.workflow_state || "";

        let status_field = "";
        let review_field = "";

        // ======================================================
        // FIND CORRECT STATUS + REVIEW FIELDS
        // ======================================================

        if (state === "Pending Team Lead Approval") {

            status_field = "lead_approver_status";
            review_field = "lead_approver_review";

        }
        else if (state === "Pending Level 2.1 Legal Approval") {

            status_field = "legal_approver_status";
            review_field = "legal_approver_review";

        }
        else if (state === "Pending Level 2.2 Finance Approval") {

            status_field = "finance_approver_status";
            review_field = "finance_approver_review";

        }
        else if (state === "Pending Level 2.3 HR Approval") {

            status_field = "hr_approver_status";
            review_field = "hr_approver_review";

        }
        else if (state === "Pending CEO Approval") {

            status_field = "ceo_approver_status";
            review_field = "ceo_approver_review";
        }

        // ======================================================
        // SAFETY CHECK
        // ======================================================

        if (!status_field || !review_field) {

            frappe.msgprint({
                title: "Workflow Error",
                indicator: "red",
                message:
                    "Could not determine the correct approver status/review fields."
            });

            return Promise.reject("NO_STATUS_OR_REVIEW_FIELD");
        }

        // Unfreeze page
        frappe.dom.unfreeze();

        // ======================================================
        // WAIT FOR REJECTION POPUP
        // ======================================================

        return new Promise(function(resolve, reject) {

            let submitted = false;

            // ==================================================
            // CREATE REJECTION POPUP
            // ==================================================

            let dialog = new frappe.ui.Dialog({

                title: "Reject Contract",

                fields: [
                    {
                        label: "Reason for Rejection",
                        fieldname: "reason",
                        fieldtype: "Small Text",
                        reqd: 1,
                        description:
                            "Please provide the reason for rejecting this contract."
                    }
                ],

                primary_action_label: "Submit Rejection",

                // ==================================================
                // SUBMIT REJECTION
                // ==================================================

                primary_action: async function(values) {

                    let reason =
                        values.reason
                            ? values.reason.trim()
                            : "";

                    // Reason required
                    if (!reason) {

                        frappe.msgprint({
                            title: "Reason Required",
                            indicator: "red",
                            message:
                                "Please enter a reason before submitting the rejection."
                        });

                        return;
                    }

                    // ==================================================
                    // DATE + TIME
                    // ==================================================

                    let timestamp =
                        frappe.datetime.now_datetime();

                    let display_timestamp =
                        frappe.datetime.str_to_user(timestamp);

                    // ==================================================
                    // CREATE STATUS TEXT
                    // ==================================================

                    let status_text =
                        "Rejected [" +
                        display_timestamp +
                        "]";

                    // ==================================================
                    // PUT BOTH VALUES INTO FORM
                    //
                    // IMPORTANT:
                    // We do NOT use frappe.client.set_value here.
                    // Both fields will be saved together.
                    // ==================================================

                    await frm.set_value(
                        status_field,
                        status_text
                    );

                    await frm.set_value(
                        review_field,
                        reason
                    );

                    frm.refresh_field(status_field);
                    frm.refresh_field(review_field);

                    // ==================================================
                    // SAVE BOTH VALUES ONCE
                    // ==================================================

                    try {

                        await frm.save();

                    }
                    catch (error) {

                        console.error(
                            "Could not save rejection:",
                            error
                        );

                        frappe.msgprint({
                            title: "Rejection Failed",
                            indicator: "red",
                            message:
                                "The rejection status and review could not be saved. Please try again."
                        });

                        return;
                    }

                    // ==================================================
                    // MARK AS SUBMITTED
                    // ==================================================

                    submitted = true;

                    // Close popup
                    dialog.hide();

                    // ==================================================
                    // CONSOLE LOG
                    // ==================================================

                    console.log(
                        "Rejection status:",
                        status_field,
                        status_text
                    );

                    console.log(
                        "Rejection review:",
                        review_field,
                        reason
                    );

                    // ==================================================
                    // ALLOW WORKFLOW TO CONTINUE
                    // ==================================================

                    resolve();
                }
            });

            // ======================================================
            // SHOW POPUP
            // ======================================================

            dialog.show();

            // ======================================================
            // FOCUS REASON FIELD
            // ======================================================

            setTimeout(function() {

                if (
                    dialog.fields_dict &&
                    dialog.fields_dict.reason &&
                    dialog.fields_dict.reason.$input
                ) {

                    dialog.fields_dict.reason.$input.focus();
                }

            }, 200);

            // ======================================================
            // HANDLE X BUTTON
            // ======================================================

            dialog.$wrapper
                .find(".modal-header .close")
                .off("click.reject_contract")
                .on(
                    "click.reject_contract",
                    function() {

                        if (submitted) {
                            return;
                        }

                        dialog.hide();

                        frappe.show_alert({
                            message: "Rejection cancelled.",
                            indicator: "orange"
                        });

                        reject("REJECTION_CANCELLED");
                    }
                );

            // ======================================================
            // HANDLE ESC / MODAL HIDE
            // ======================================================

            dialog.$wrapper
                .off("hidden.bs.modal.reject_contract")
                .on(
                    "hidden.bs.modal.reject_contract",
                    function() {

                        if (submitted) {
                            return;
                        }

                        reject("REJECTION_CANCELLED");
                    }
                );

        });
    }

});

