frappe.ui.form.on("Employee", {
    refresh: function(frm) {

        setTimeout(function() {

            let table = frm.fields_dict.custom_organizational_structure;

            if (!table || !table.grid) {
                return;
            }

            // Get the child table grid
            let grid = table.grid;

            // Set PDF-only restriction on the Upload field
            if (grid.docfields) {
                let upload_field = grid.docfields.find(
                    df => df.fieldname === "upload"
                );

                if (upload_field) {
                    upload_field.options = ".pdf";
                }
            }

            // Set PDF-only restriction on file input
            grid.wrapper
                .find('input[type="file"]')
                .attr("accept", ".pdf,application/pdf");

            // Observe newly created file inputs inside the child table
            if (!grid.wrapper.data("pdf-upload-observer")) {

                let observer = new MutationObserver(function() {

                    grid.wrapper
                        .find('input[type="file"]')
                        .attr("accept", ".pdf,application/pdf");

                });

                observer.observe(grid.wrapper[0], {
                    childList: true,
                    subtree: true
                });

                grid.wrapper.data("pdf-upload-observer", observer);
            }

        }, 500);
    },

    validate: function(frm) {

        let rows = frm.doc.custom_acknowledgement_forms_ || [];

        for (let row of rows) {

            if (row.upload) {

                let filename = row.upload.split("/").pop().toLowerCase();

                if (!filename.endsWith(".pdf")) {

                    frappe.msgprint({
                        title: "Invalid File",
                        message: "Only PDF files are allowed in the Employment Life Cycle Documents upload field.",
                        indicator: "red"
                    });

                    frappe.model.set_value(
                        row.doctype,
                        row.name,
                        "upload",
                        ""
                    );

                    frappe.validated = false;
                    return false;
                }
            }
        }
    }
});

frappe.ui.form.on("Employee", {

    // Runs when Primary is changed inside the child table
    custom_organization_associations_add: function(frm, cdt, cdn) {
        check_primary_organization(frm);
    },

    validate: function(frm) {
        check_primary_organization(frm);
    }
});


function check_primary_organization(frm) {

    const rows = frm.doc.custom_organization_associations || [];

    const primary_rows = rows.filter(
        row => Number(row.primary) === 1
    );

    // More than one Primary Organization
    if (primary_rows.length > 1) {

        frappe.throw(
            "Only one Primary Organization can be assigned to an employee."
        );
    }

    // Primary Organization must be Active
    if (primary_rows.length === 1) {

        const primary_row = primary_rows[0];

        if (Number(primary_row.active) !== 1) {

            frappe.throw(
                "The Primary Organization must be Active."
            );
        }
    }
}

frappe.ui.form.on("Employee", {

    validate: function(frm) {

        const rows = frm.doc.custom_organization_associations || [];

        const primary_rows = rows.filter(
            row => Number(row.primary) === 1
        );

        if (primary_rows.length > 1) {

            frappe.throw(
                "Only one Primary Organization can be assigned to an employee."
            );
        }

        if (primary_rows.length === 1) {

            const primary_row = primary_rows[0];

            if (Number(primary_row.active) !== 1) {

                frappe.throw(
                    "The Primary Organization must be Active."
                );
            }
        }
    }
});


frappe.ui.form.on("Employee Organization Association", {

    primary: function(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        // Primary must be Active
        if (
            Number(row.primary) === 1 &&
            Number(row.active) !== 1
        ) {

            frappe.msgprint(
                "The Primary Organization must be Active."
            );

            frappe.model.set_value(
                cdt,
                cdn,
                "primary",
                0
            );

            return;
        }

        const rows = frm.doc.custom_organization_associations || [];

        const primary_rows = rows.filter(
            r => Number(r.primary) === 1
        );

        // Only one Primary
        if (primary_rows.length > 1) {

            frappe.msgprint(
                "Only one Primary Organization can be assigned to an employee."
            );

            frappe.model.set_value(
                cdt,
                cdn,
                "primary",
                0
            );
        }
    },


    active: function(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        // Primary cannot be inactive
        if (
            Number(row.primary) === 1 &&
            Number(row.active) !== 1
        ) {

            frappe.msgprint(
                "The Primary Organization must be Active."
            );

            frappe.model.set_value(
                cdt,
                cdn,
                "active",
                1
            );
        }
    }
});

frappe.ui.form.on('Leave Application', {
    refresh: function(frm) {
        render_unified_leave_dashboard(frm);
    },
    employee: function(frm) {
        render_unified_leave_dashboard(frm);
    },
    from_date: function(frm) {
        render_unified_leave_dashboard(frm);
    },
    to_date: function(frm) {
        render_unified_leave_dashboard(frm);
    },
    leave_type: function(frm) {
        if (frm.doc.leave_type && frm.doc.leave_type.toLowerCase().includes("maternity")) {
            if (frm._employee_gender && frm._employee_gender !== "Female") {
                frappe.msgprint({
                    title: __("Not Applicable"),
                    message: __("Maternity Leave is only applicable for female employees."),
                    indicator: "red"
                });
                frm.set_value("leave_type", "");
            }
        }
    },
    validate: function(frm) {
        if (frm.doc.leave_type && frm.doc.leave_type.toLowerCase().includes("maternity")) {
            if (frm._employee_gender && frm._employee_gender !== "Female") {
                frappe.msgprint(__("Maternity Leave is only applicable for female employees."));
                frappe.validated = false;
            }
        }
    }
});

function render_unified_leave_dashboard(frm) {
    if (!frm.doc.employee) return;

    let year = (frm.doc.from_date || frm.doc.posting_date || frappe.datetime.get_today()).substring(0, 4);

    frappe.db.get_value("Employee", frm.doc.employee, "gender", function(r) {
        frm._employee_gender = (r && r.gender) ? r.gender : "";

        frappe.call({
            method: "get_unified_leave_details",
            args: {
                employee: frm.doc.employee,
                year: year
            },
            callback: function(res) {
                if (res.message && res.message.leave_details) {
                    let details = res.message.leave_details;

                    // Remove standard and custom dashboard sections
                    $("div").remove(".form-dashboard-section.custom");

                    frm.dashboard.add_section(
                        frappe.render_template("leave_application_dashboard", {
                            data: details
                        }),
                        __("Allocated Leaves")
                    );
                    frm.dashboard.show();

                    customize_allocation_table(frm);

                    let allowed_types = Object.keys(details);
                    if (frm._employee_gender !== "Female") {
                        allowed_types = allowed_types.filter(t => !t.toLowerCase().includes("maternity"));
                    }

                    frm.set_query("leave_type", function() {
                        return {
                            filters: [["Leave Type", "name", "in", allowed_types]]
                        };
                    });
                }
            }
        });
    });
}

function customize_allocation_table(frm) {
    let check_exist = setInterval(function() {
        let expired_th = $(frm.wrapper).find("th:contains('Expired Leaves')");
        let available_th = $(frm.wrapper).find("th:contains('Available Leaves')");

        if (expired_th.length > 0 || available_th.length > 0) {
            if (available_th.length > 0) {
                available_th.text("Balance Leaves");
            }

            if (expired_th.length > 0) {
                let col_index = expired_th.index();
                let table = expired_th.closest('table');

                expired_th.hide();
                table.find("tr").each(function() {
                    $(this).find(`td:eq(${col_index})`).hide();
                });
            }

            if (frm._employee_gender && frm._employee_gender !== "Female") {
                $(frm.wrapper).find("table tbody tr").each(function() {
                    let leave_name = $(this).find("td:first").text().toLowerCase();
                    if (leave_name.includes("maternity")) {
                        $(this).hide();
                    }
                });
            }

            clearInterval(check_exist);
        }
    }, 300);

    setTimeout(() => clearInterval(check_exist), 6000);
}

