function handle_increment_row_added(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    let rows = frm.doc.custom_increment_history || [];
    let base_salary = 0;

    // Pull from previous row's revised salary, or parent custom_annual_salary
    let prev_rows = rows.filter(r => r.name !== cdn);
    if (prev_rows.length > 0) {
        let prev = prev_rows[prev_rows.length - 1];
        base_salary = flt(prev.revised_annual_salary) || flt(prev.current_annual_salary) || flt(frm.doc.custom_annual_salary) || 0;
    } else {
        base_salary = flt(frm.doc.custom_annual_salary) || 0;
    }

    if (base_salary > 0) {
        frappe.model.set_value(cdt, cdn, 'current_annual_salary', base_salary);
    }
    if (frm.doc.salary_currency) {
        frappe.model.set_value(cdt, cdn, 'currency', frm.doc.salary_currency);
    }

    frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', 0);
    frappe.model.set_value(cdt, cdn, 'revised_annual_salary', 0);

    refresh_increment_grid_row(frm, cdn);
    setTimeout(() => { refresh_increment_grid_row(frm, cdn); }, 50);
    setTimeout(() => { refresh_increment_grid_row(frm, cdn); frm.refresh_field('custom_increment_history'); }, 150);
}

function ensure_row_current_salary(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;
    if (!flt(row.current_annual_salary)) {
        handle_increment_row_added(frm, cdt, cdn);
    }
}

// CALCULATION A: Triggered when user enters Increment by Amount
function calc_from_amount(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    let current = flt(row.current_annual_salary);
    let amount = flt(row.custom_increment_by_amount);

    if (current > 0 && amount > 0) {
        let pct = (amount / current) * 100.0;
        let revised = current + amount;

        // Auto-calculates the percentage (rounded to 2 decimal places) and revised salary
        frappe.model.set_value(cdt, cdn, 'increment_percentage', flt(pct.toFixed(2)));
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', revised);
    } else if (amount <= 0 && flt(row.increment_percentage) <= 0) {
        frappe.model.set_value(cdt, cdn, 'increment_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', 0);
    }

    update_parent_annual_salary_from_increments(frm);
    refresh_increment_grid_row(frm, cdn);
}

// CALCULATION B: Triggered when user enters Increment Percentage
function calc_from_percentage(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    let current = flt(row.current_annual_salary);
    let pct = flt(row.increment_percentage);

    if (current > 0 && pct > 0) {
        let amount = current * (pct / 100.0);
        let revised = current + amount;

        // Auto-calculates the amount and revised salary
        frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', amount);
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', revised);
    } else if (pct <= 0 && flt(row.custom_increment_by_amount) <= 0) {
        frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', 0);
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', 0);
    }

    update_parent_annual_salary_from_increments(frm);
    refresh_increment_grid_row(frm, cdn);
}

function refresh_increment_grid_row(frm, cdn) {
    let grid = frm.fields_dict['custom_increment_history'] && frm.fields_dict['custom_increment_history'].grid;
    if (grid && grid.grid_rows_by_docname && grid.grid_rows_by_docname[cdn]) {
        let grid_row = grid.grid_rows_by_docname[cdn];
        grid_row.refresh_field('current_annual_salary');
        grid_row.refresh_field('custom_increment_by_amount');
        grid_row.refresh_field('increment_percentage');
        grid_row.refresh_field('revised_annual_salary');
        if (frm.doc.salary_currency) {
            grid_row.refresh_field('currency');
        }
    }
}

function update_parent_annual_salary_from_increments(frm) {
    let rows = frm.doc.custom_increment_history || [];
    let latest_revised = 0;

    for (let i = rows.length - 1; i >= 0; i--) {
        if (flt(rows[i].revised_annual_salary) > 0) {
            latest_revised = flt(rows[i].revised_annual_salary);
            break;
        }
    }

    if (latest_revised > 0) {
        frm.set_value('custom_annual_salary', latest_revised);
        frm.refresh_field('custom_annual_salary');
    }
}

