    },
    onload_post_render: function(frm) {
        setup_aadhaar_input_mask(frm);
    },
    custom_aadhaar: function(frm) {
        format_aadhaar_value(frm);
    },
    validate: function(frm) {
        if (frm.doc.custom_aadhaar) {
            let raw = (frm.doc.custom_aadhaar || '').replace(/\D/g, '');
            if (raw.length !== 12) {
                frappe.msgprint({
                    title: __('Invalid Aadhaar Number'),
                    indicator: 'red',
                    message: __('<b>Aadhaar</b> must be exactly 12 digits in the format <b>XXXX XXXX XXXX</b> (14 characters with spaces).')
                });
                frappe.validated = false;
                return false;
            }
            let formatted = raw.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
            frm.doc.custom_aadhaar = formatted;
            frm.refresh_field('custom_aadhaar');
        }
    }
});

function setup_aadhaar_input_mask(frm) {
    let field = frm.get_field('custom_aadhaar');
    if (field && field.$input) {
        field.$input.attr('maxlength', 14);
        field.$input.attr('placeholder', 'XXXX XXXX XXXX');
        field.$input.off('input.aadhaar_mask').on('input.aadhaar_mask', function(e) {
            let val = this.value.replace(/\D/g, '').substring(0, 12);
            let formatted = val.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
            this.value = formatted;
        });
    }
}

function format_aadhaar_value(frm) {
    if (!frm.doc.custom_aadhaar) return;
    let raw = frm.doc.custom_aadhaar.replace(/\D/g, '').substring(0, 12);
    let formatted = raw.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
    if (frm.doc.custom_aadhaar !== formatted) {
        frm.set_value('custom_aadhaar', formatted);
    }
}

// ============================================================
// LEAVE POLICY REVISION FORM CONTROLS & HIGHLIGHTING
// ============================================================

function calculate_next_version(old_text) {
    if (!old_text || !old_text.trim()) {
        return "1";
    }
    let regex = /\[1(?:\.(\d+))?\]/g;
    let match;
    let max_minor = 0;
    let has_sub = false;
    while ((match = regex.exec(old_text)) !== null) {
        if (match[1]) {
            has_sub = true;
            let n = parseInt(match[1], 10);
            if (!isNaN(n) && n > max_minor) max_minor = n;
        }
    }
    if (has_sub) {
        return "1." + (max_minor + 1);
    } else {
        return "1.1";
    }
}

frappe.ui.form.on("Leave Policy", {
    setup: function(frm) {
        frm.set_query("ceo_approver", function() {
            return {
                query: "frappe.core.doctype.user.user.user_query",
                filters: frm._ceo_approver_filters || {}
            };
        });

        frappe.call({
            method: "get_ceo_approvers",
            callback: function(r) {
                if (r.message && r.message.length) {
                    let allowed_users = r.message.map(d => d.name);
                    frm._ceo_approver_filters = {
                        name: ["in", allowed_users]
                    };
                }
            }
        });
    },

    onload: function(frm) {
        if (!frm._ceo_approver_filters) {
            frappe.call({
                method: "get_ceo_approvers",
                callback: function(r) {
                    if (r.message && r.message.length) {
                        let allowed_users = r.message.map(d => d.name);
                        frm._ceo_approver_filters = {
                            name: ["in", allowed_users]
                        };
                    }
                }
            });
        }
    },

    refresh: function(frm) {
        // Lock CEO Approver if submitted/approved, allow selection during Draft / Setup
        if (frm.doc.docstatus === 1 && frm.doc.workflow_state !== "Revision in Progress") {
            frm.set_df_property("ceo_approver", "read_only", 1);
        } else {
            frm.set_df_property("ceo_approver", "read_only", 0);
        }

        // 1. Grid Column Formatter: Highlight updated/new rows
        if (frm.fields_dict.leave_policy_details && frm.fields_dict.leave_policy_details.grid) {
            let grid = frm.fields_dict.leave_policy_details.grid;
            let fld = grid.get_field("last_updated_on");
            if (fld) {
                fld.formatter = function(value, df, options, doc) {
                    if (!value) return '<span style="color:#9ca3af; font-size:11px;">—</span>';

                    let user_date = frappe.datetime.str_to_user(value);

                    let is_revised = false;
                    if (frm.doc.creation && value) {
                        let creation_time = frappe.datetime.str_to_obj(frm.doc.creation);
                        let update_time = frappe.datetime.str_to_obj(value);
                        if (update_time && creation_time && (update_time - creation_time > 60000)) {
                            is_revised = true;
                        }
                    }

                    if (is_revised) {
                        return `<span style="background-color: #dcfce7; color: #15803d; border: 1px solid #86efac; padding: 2px 8px; border-radius: 12px; font-weight: 600; font-size: 11px; display: inline-flex; align-items: center; gap: 5px;">
                            <span style="width: 6px; height: 6px; border-radius: 50%; background-color: #22c55e; display: inline-block;"></span>
                            ${user_date} <span style="font-size: 10px; opacity: 0.85;">(Updated)</span>
                        </span>`;
                    } else {
                        return `<span style="color: #4b5563; font-size: 11.5px; display: inline-block; padding: 2px 4px;">
                            ${user_date}
                        </span>`;
                    }
                };
            }
        }

        // 2. Lock / Unlock child table based on workflow state
        if (!frm.doc.__islocal && frm.doc.docstatus === 1) {
            if (frm.doc.workflow_state === "Revision in Progress") {
                frm.set_df_property("leave_policy_details", "read_only", 0);
                if (frm.fields_dict.leave_policy_details && frm.fields_dict.leave_policy_details.grid) {
                    frm.fields_dict.leave_policy_details.grid.cannot_add_rows = false;
                    frm.fields_dict.leave_policy_details.grid.df.cannot_add_rows = false;
                    frm.fields_dict.leave_policy_details.grid.refresh();
                }
            } else {
                frm.set_df_property("leave_policy_details", "read_only", 1);
                if (frm.fields_dict.leave_policy_details && frm.fields_dict.leave_policy_details.grid) {
                    frm.fields_dict.leave_policy_details.grid.cannot_add_rows = true;
                    frm.fields_dict.leave_policy_details.grid.df.cannot_add_rows = true;
                    frm.fields_dict.leave_policy_details.grid.refresh();
                }
            }
        }

        // 3. Status Color in Approver Details (Clean single value, bold colored)
        frm.set_df_property("ceo_approver_status", "description", "");
        if (frm.doc.ceo_approver_status && frm.fields_dict.ceo_approver_status && frm.fields_dict.ceo_approver_status.$wrapper) {
            let status = frm.doc.ceo_approver_status;
            let color = status === "Approved" ? "#16a34a" : (status === "Rejected" ? "#dc2626" : "#d97706");
            frm.fields_dict.ceo_approver_status.$wrapper.find(".control-value, input").css({
                "color": color,
                "font-weight": "600"
            });
        }
    },

    // 4. Intercept CEO Approval & Rejection with Version-Tracked Comments (1, 1.1, 1.2...)
    before_workflow_action: function(frm) {
        let action = (frm.selected_workflow_action || "").trim();
        let action_lower = action.toLowerCase();

        let is_approval = action_lower === "approve" || action_lower === "approve revision";
        let is_rejection = action_lower === "reject" || action_lower === "reject revision";

        if (!is_approval && !is_rejection) {
            return; // Allow normal actions like 'Request Revision', 'Submit for Approval', etc.
        }

        frappe.dom.unfreeze();

        return new Promise(function(resolve, reject) {
            let dialog_title = is_approval ? __("Approve Leave Policy") : __("Reject Leave Policy");

            let dialog = new frappe.ui.Dialog({
                title: dialog_title,
                fields: [
                    {
                        label: is_approval ? __("Review Comments (Optional)") : __("Reason for Rejection"),
                        fieldname: "comments",
                        fieldtype: "Small Text",
                        reqd: is_rejection ? 1 : 0,
                        description: is_approval 
                            ? __("Add any remarks or directives for the policy approval.") 
                            : __("Please provide the specific reason for rejecting this policy.")
                    }
                ],
                primary_action_label: is_approval ? __("Confirm Approval") : __("Submit Rejection"),
                primary_action: function(values) {
                    let user_comments = (values.comments || "").trim();
                    let approver_user = frappe.session.user;
                    let approver_status = is_approval ? "Approved" : "Rejected";
                    let approver_name = (frappe.user_info(approver_user) && frappe.user_info(approver_user).fullname) 
                        ? frappe.user_info(approver_user).fullname 
                        : approver_user;
                    let now_time = frappe.datetime.now_datetime();

                    // Calculate next version track (1 -> 1.1 -> 1.2 ...)
                    let old_trail = (frm.doc.ceo_approver_comments || "").trim();
                    let next_ver = calculate_next_version(old_trail);

                    let entry_body = user_comments ? user_comments : (is_approval ? "Approved." : "Rejected.");
                    let new_entry = `[${next_ver}] (${now_time}) - ${approver_status} by ${approver_name}:
${entry_body}`;

                    let full_trail = old_trail 
                        ? `${old_trail}

----------------------------------------
${new_entry}`
                        : new_entry;

                    // Persist directly to DB before apply_workflow runs doc.load_from_db()
                    frappe.call({
                        method: "frappe.client.set_value",
                        args: {
                            doctype: "Leave Policy",
                            name: frm.doc.name,
                            fieldname: {
                                "ceo_approver": approver_user,
                                "ceo_approver_status": approver_status,
                                "ceo_approver_comments": full_trail
                            }
                        },
                        freeze: true,
                        freeze_message: __("Recording decision..."),
                        callback: function(r) {
                            frm.doc.ceo_approver = approver_user;
                            frm.doc.ceo_approver_status = approver_status;
                            frm.doc.ceo_approver_comments = full_trail;
                            frm.refresh_fields(["ceo_approver", "ceo_approver_status", "ceo_approver_comments"]);
                            dialog.hide();
                            resolve();
                        },
                        error: function(err) {
                            frappe.dom.unfreeze();
                            reject(err);
                        }
                    });
                }
            });

            // If CEO cancels the dialog without submitting on rejection, abort
            dialog.on_hide = function() {
                if (is_rejection && !dialog.get_value("comments")) {
                    reject("ACTION_CANCELLED");
                }
            };

            // Style the primary button
            if (is_rejection) {
                dialog.get_primary_btn().removeClass("btn-primary").addClass("btn-danger");
            } else {
                dialog.get_primary_btn().removeClass("btn-primary").addClass("btn-success");
            }

            dialog.show();
        });
    }
});

frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        setup_pan_input_mask(frm);
    },
    onload_post_render: function(frm) {
        setup_pan_input_mask(frm);
    },
    pan_number: function(frm) {
        format_pan_value(frm);
    },
    validate: function(frm) {
        if (frm.doc.pan_number) {
            let pan = (frm.doc.pan_number || '').trim().toUpperCase();
            frm.doc.pan_number = pan;

            // Regex for Indian PAN: 5 Letters + 4 Digits + 1 Letter
            let pan_regex = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;

            if (!pan_regex.test(pan)) {
                frappe.msgprint({
                    title: __('Invalid PAN Number'),
                    indicator: 'red',
                    message: __('<b>PAN Number</b> must be a valid 10-character alphanumeric code in the format <b>AAAAA9999A</b> (5 letters, 4 digits, 1 letter, e.g., <b>ABCPB1234K</b>).')
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

function setup_pan_input_mask(frm) {
    let field = frm.get_field('pan_number');
    if (field && field.$input) {
        field.$input.attr('maxlength', 10);
        field.$input.attr('placeholder', 'ABCDE1234F');
        field.$input.css('text-transform', 'uppercase');

        field.$input.off('input.pan_mask').on('input.pan_mask', function(e) {
            let val = (this.value || '').toUpperCase().replace(/[^A-Z0-9]/g, '').substring(0, 10);
            this.value = val;
        });
    }
}

function format_pan_value(frm) {
    if (!frm.doc.pan_number) return;
    let clean = (frm.doc.pan_number || '').toUpperCase().replace(/[^A-Z0-9]/g, '').substring(0, 10);
    if (frm.doc.pan_number !== clean) {
        frm.set_value('pan_number', clean);
    }
}

