// ============================================================

function check_edu_certificate_pdf(frm, cdt, cdn, fieldname, label) {
    let row = locals[cdt][cdn];
    let val = row[fieldname];
    if (val) {
        let clean_val = val.split("?")[0];
        let filename = clean_val.split("/").pop().toLowerCase();
        if (!filename.endsWith(".pdf")) {
            frappe.model.set_value(cdt, cdn, fieldname, "");
            frappe.msgprint({
                title: __("Invalid File Format"),
                indicator: "red",
                message: __("<b>Only PDF files are permitted</b> for Educational Certificates.<br><br>The uploaded file <code>{0}</code> is not a PDF.", [filename])
            });
            return false;
        }
    }
    return true;
}

