// Parent Form Validation on Save
frappe.ui.form.on("Employee", {
    validate: function(frm) {
        let cert_fields = ["certificate", "certificate_2", "certificate_3", "certificate_4", "certificate_5"];
        let edu_rows = frm.doc.education || [];

        for (let row of edu_rows) {
            for (let f of cert_fields) {
                let val = row[f];
                if (val) {
                    let clean_val = val.split("?")[0];
                    let filename = clean_val.split("/").pop().toLowerCase();
                    if (!filename.endsWith(".pdf")) {
                        frappe.msgprint({
                            title: __("Invalid Attachment"),
                            indicator: "red",
                            message: __("<b>Educational Qualification (Row #{0}):</b><br>Only PDF files are allowed. The file <code>{1}</code> is not a PDF. Please replace it with a valid PDF file.", [row.idx, filename])
                        });
                        frappe.validated = false;
                        return false;
                    }
                }
            }
        }
    }
});





